learn=[('Package the actual SDK service', 'Compile TypeScript in a Linux build stage and retain the platform-specific optional CLI dependency. Run the HTTP service and its real SDK subprocess as the node user.'), ('Inject private configuration at runtime', 'Keep the model key out of source and image layers. The lab creates short-lived private env files and separate random service/store tokens; it never displays their values.'), ('Move transcripts outside replicas', 'The SDK mirrors transcript entries to a separate authenticated HTTP store backed by its own Docker volume. The store also maps trusted classroom identities to session IDs.'), ('Replace and alternate containers', 'Resume the same session after replacing a replica or sending the next turn to a different replica. A matching per-tenant working directory lets the external transcript hydrate correctly.'), ('Test deployment boundaries', 'Observe actual non-root IDs, read-only root filesystems, CPU/memory/PID limits, rejected authentication and distinct tenant sessions. These examples expose no agent tools.'), ('Handle persistence failures honestly', 'A mirror_error is a durability failure even when a model answer succeeds. Do not commit a failed transcript mapping. Recover the store with the same volume and verify recall of previously committed turns.')]
labels=[('baseline', 'Baseline: actual containerized query'), ('resume', 'Resume a conversation from the store'), ('replace', 'Replace the agent container and recall'), ('replicas', 'Alternate A → B → A'), ('tenant', 'Keep Alice and Bob sessions separate'), ('auth', 'Reject a request without the gateway token'), ('limits', 'Inspect limits and actual read-only denial'), ('mirror', 'Observe a real transcript-mirror outage'), ('recovery', 'Restart the store and replica; recover')]
runsteps=[('Prerequisites', 'Install Node.js 24+ and Docker Desktop with its Linux engine running. Use a model available to your account and sufficient API credit. Native Windows may require Git Bash for local SDK lessons; this lesson executes the CLI inside Linux containers.', 'node --version\nnpm --version\ndocker version'), ('Install and configure privately', 'From presentations use the path below; skip cd inside a standalone clone. Preserve an existing .env and enter your own API key privately. No Redis account, Managed Agents IDs or GitHub token is needed.', 'cd .\\agent-sdk\\lesson58-docker-deployment\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Build the Linux image', 'npm ci runs inside the image so the optional native CLI matches Linux. The Docker build context excludes your .env, dependencies, media and Git history. No key is supplied to docker build.', 'npm run docker:build'), ('Run the student web lab', 'Keep the terminal open and open the displayed URL. Choose Baseline first, then Resume, Replace, Replicas and Recovery. Each experiment starts its own store plus two replicas, makes real model requests, records evidence and removes only its own UUID-named resources afterward.', 'npm start\n# http://127.0.0.1:3158'), ('Verify and run from a terminal', 'Tests use temporary directories and no model calls. Live pipeline commands require Docker and model credit. They inspect real Docker configuration and actual native results; provider waits can take a while.', 'npm test\nnpm run pipeline -- baseline\nnpm run pipeline -- replace\nnpm run pipeline -- replicas'), ('Explore failures and evidence', 'Mirror temporarily rejects transcript appends in its own external store. The old committed Alice session stays usable, while Bob’s failed transcript is not committed. Recovery removes and recreates the store container with the same owned volume. Do not treat this single-writer classroom service as a production HA database.', 'npm run pipeline -- mirror\nnpm run pipeline -- recovery\n# Sanitized evidence: .runtime/runs/<run-id>/evidence.json\n# Replica ports bind to 127.0.0.1 only; no public deployment is created.')]
specs=[('Build for the target Linux platform', 'Dockerfile', 'FROM node:24', 'The build stage installs the pinned SDK inside Linux. Keep its optional native CLI dependencies and compile the server. The separate runtime stage omits dev dependencies.', 0, 1, 8), ('Run a non-root runtime image', 'Dockerfile', 'COPY --from=build /app/node_modules', 'Copy the compiled app and runtime dependencies, select the node user and start the actual HTTP SDK service. No model key is baked into the image.', 1, 2, 8), ('Inject private runtime configuration', 'src/deployment.ts', 'const key=', 'Write the private model key and per-run service credentials to an ignored temporary env file. Docker receives the filename; credentials never appear in recorded command arguments or UI evidence.', 0, 1, 13), ('Apply container resource boundaries', 'src/deployment.ts', 'return [', 'Run replicas with a read-only root, bounded memory/CPU/PIDs, dropped capabilities, no-new-privileges and explicit writable tmpfs paths. Model API access still needs the bridge network.', 1, 2, 15), ('Authenticate the incoming request', 'src/service.ts', 'if(req.headers.authorization', 'Require the random classroom gateway credential before chat or store operations. The browser cannot supply user identities; the host harness chooses Alice or Bob. This is a local teaching gateway, not a production identity provider.', 1, 2, 5), ('Resolve identity and serialize turns', 'src/service.ts', 'const tenant=req.headers', 'Use only the authenticated gateway’s known identity, reject invalid tasks and acquire the external per-tenant lease. Limit active queries per replica so concurrent turns cannot race within the demonstrated session.', 2, 4, 6), ('Load the retained session ID', 'src/service.ts', 'const resume=', 'Get the tenant’s committed session ID from the external store. Use the same per-tenant working directory in every replica and pass resume plus the actual SessionStore adapter to the SDK.', 2, 4, 7), ('Invoke query inside the container', 'src/service.ts', 'run=query', 'The real SDK starts its CLI subprocess inside the non-root agent container and yields actual messages. Observe native init IDs, text, mirror failures and terminal results; no model response is simulated.', 2, 3, 7), ('Mirror transcript entries externally', 'src/remote-store.ts', 'async append', 'Send actual SDK transcript entries to the authenticated external writer and record only entry counts and IDs in browser evidence. This store mirrors transcripts, not arbitrary workspace files or memory.', 3, 4, 8), ('Commit after the mirror flush', 'src/service.ts', '// Wait for the SDK iterator', 'Wait for the actual SDK iterator and final mirroring before saving a successful session mapping. A visible mirror failure prevents that commit even if the native answer succeeded.', 2, 4, 4), ('Replace a replica and hydrate', 'src/runner.ts', 'const old=', 'Delete this run’s owned agent container, launch a new one and check its actual container ID changed. The next query resumes from external storage and must recall the unpredictable conversation code.', 1, 2, 7), ('Restart the external store', 'src/deployment.ts', 'async startStore', 'Recreate the external writer with the same independent Docker volume. The Recovery case checks that both the mapping and transcript survive replacing the store and agent containers.', 1, 4, 10), ('Grade actual deployment evidence', 'src/runner.ts', 'checks.ownedResourcesCleaned', 'Require observed task checks and successful owned-resource cleanup. Persist sanitized evidence with actual native results and Docker configuration. A green label is computed from those measurements, not from fluent narration.', 1, 0, 5)]
reference=[('Scope of the deployment', 'The browser UI and bounded orchestration harness run on your computer. Actual query() and CLI run in two Linux containers. A third container is the external single-writer HTTP session store. The lab cleans up its own stack after each experiment.'), ('External store versus production storage', 'The HTTP adapter is implemented in this app, not a built-in RedisSessionStore class. The separate writer serializes transcript appends and uses atomic file replacement on its own volume. Production systems need transactional/CAS semantics, durable infrastructure, tenancy authorization, retention, encryption, lease expiry and HA.'), ('Gateway and tenant boundary', 'Random per-run bearer credentials authenticate harness requests. The trusted harness supplies only Alice or Bob. Session IDs are looked up server-side and never accepted from the browser. This demonstrates the contract for a real authentication gateway without claiming to implement public login.'), ('Durability and interruption', 'Replacement tests cover completed, committed turns. They do not promise that a turn killed mid-generation is fully durable. Eager mirroring reduces the unflushed window; final persistence errors still matter. The independent store volume survives its container replacement and is deleted only when the experiment is over.'), ('Resources and isolation', 'The actual inspect evidence includes user, CPU/memory/PID limits, read-only root, mount types and dropped capabilities. The SDK has no tools in this memory exercise. A distinct cwd alone is not an operating-system tenant boundary. Resource values are classroom settings; measure your real workload rather than assuming a universal RAM requirement.'), ('Telemetry for a production exercise', 'Native SDK messages, HTTP statuses, mirror errors and Docker inspect data are captured here. OTLP export is not enabled in this small lab. To extend it, configure CLAUDE_CODE_ENABLE_TELEMETRY=1, OTEL_METRICS_EXPORTER=otlp, OTEL_EXPORTER_OTLP_ENDPOINT and OTEL_SERVICE_NAME with a private collector. Avoid raw prompts, keys or transcripts in telemetry; observe mirror_error alerts.'), ('Primary references', 'https://platform.claude.com/docs/en/agent-sdk/hosting ; https://github.com/anthropics/claude-agent-sdk-typescript/tree/main/examples/session-stores ; https://docs.docker.com/build/building/multi-stage/ ; https://docs.docker.com/engine/containers/resource_constraints/ ; Original teaching deck: Lesson58_Build_Deploying_with_Docker.pptx')]

env="ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3158\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe"
select=''.join(f'<option value="{m}">{escape(t)}</option>' for m,t in labels)
body='<section class="panel" id="controls"><h2>Run a Docker deployment experiment</h2><p id="configuration">Checking configuration...</p><label for="mode">Experiment</label><select id="mode">'+select+'</select><div class="actions"><button class="primary" id="run" disabled>Run real Docker experiment →</button><button id="download">Download actual evidence</button></div><p class="note">Each experiment starts real Docker services and makes real SDK queries. Inspect native results, container boundaries, session IDs and external-store recovery. Only owned resources are removed at the end.</p><p id="status" role="status">Choose an experiment.</p></section>'
body+='<div class="grid"><article class="card"><h3>Actual worker exit</h3><p id="span-count">Pending</p></article><article class="card"><h3>Native results</h3><p id="metric-count">0</p></article><article class="card"><h3>Actual HTTP responses</h3><p id="log-count">0</p></article></div>'
body+='<div class="workspace"><section class="panel" id="chat-panel"><h2>Actual formatted agent responses</h2><div id="conversation" class="markdown-body"></div></section><section class="panel" id="option-panel"><h2>Actual SDK configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div>'
def panel(id,title,code):return f'<section class="step" id="{id}"><h2>{title}</h2><pre class="json-view"><code id="{code}" class="language-json">{{}}</code></pre></section>'
body+='<p class="note" id="boundary-summary">SDK query() executes inside Docker. The external store is independent of both replicas.</p>'
body+=panel('process-panel','Actual process exit and case-level report','process')
body+='<section class="step" id="artifact-panel"><h2>Actual Docker configuration and deployment checks</h2><pre><code id="diff" class="language-json">Waiting for a real evaluation.</code></pre><pre class="json-view"><code id="host-checks" class="language-json">{}</code></pre></section>'
def tablepanel(id,title,heads,target,extra=''):
 return f'<section class="step" id="{id}"><h2>{title}</h2>'+extra+'<div class="table"><table><thead><tr>'+''.join('<th>'+h+'</th>'for h in heads)+f'</tr></thead><tbody id="{target}"></tbody></table></div></section>'
body+=tablepanel('trace-panel','Actual gateway and storage observations',['Event','Status / entries','Observed detail'],'trace-history')
body+=tablepanel('metric-panel','Deployment check result and observed cost',['Case','Passed / runs','Measurements and uncertainty'],'metric-history')
body+=tablepanel('model-panel','Actual harness observations',['Stage','Evidence'],'log-history','<label for="user-filter">Filter by exact observation kind</label><input id="user-filter" placeholder="configuration">')
for id,title,code in [('results-panel','Actual final native result','native-result'),('storage-panel','External session provenance','storage'),('diagnostic-panel','Incomplete runs and grader reasons','diagnostics'),('evidence-panel','All actual evaluation evidence','evidence'),('specialists-panel','All actual observations','telemetry'),('requests-panel','Native tool requests','requests')]:body+=panel(id,title,code)
document('/','Deploy agents. <em>Retain sessions.</em>','A real Docker SDK service, external transcripts, container replacement and two replicas.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Package, configure, replace and scale a containerized SDK service.',cards(learn)+actions(('/','Application lab'),('/run.html','How to run')))
run=''
for i,(title,text,code) in enumerate(runsteps,1):run+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(title)}</h2><p>{escape(text)}</p>'+snippet(code,'powershell')+(snippet(env,'ini')if i==2 else '')+'</section>'
document('/run.html','Configure and <em>run the app.</em>','Preserve your private .env. Start locally, then inspect real grades and reports.',run)
import re
steps=[];arrows=[];lanes=['Student','Docker harness','Agent service','SDK + CLI','External store']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if re.sub(r"\s+", "", anchor) in re.sub(r"\s+", "", l))
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='yaml' if source.endswith('.yml') else 'javascript' if source.endswith('.js') else 'docker' if source=='Dockerfile' else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 58 · Build → deploy → resume → replace</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{max(40,min(min(x1,x2)+10,1700-len(label)*13))}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'

document('/architecture.html','Architecture and <em>UML workflow.</em>','Every one of the thirteen steps includes matching coloured source code.','<p class="note">The host harness controls real containers. Each agent container runs query() and its CLI. The external writer stores actual transcript entries plus tenant/session mappings on an independent volume. Every step below includes matching source code.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen-step evaluation harness sequence"></div>'+walk)
document('/walkthrough.html','How the app <em>was built.</em>','Read the actual Docker service and external session store.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 58 · Deploying with Docker\n\nFive student pages, thirteen source-linked UML steps and nine actual Docker deployment experiments.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n'for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson58-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson58-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations: `cd .\\agent-sdk\\lesson58-docker-deployment`. Open http://127.0.0.1:3158. Node 24+, model API credit, and Windows Git Bash if required.\n'
readme+='\n## Create your .env file\n\nPreserve the real file locally and enter your own key. Restart after edits. Existing shell values take precedence. No secret is included in source.\n\n```dotenv\n'+env+'\n```\n'
for title,text,code in runsteps[3:]:readme+='\n## '+title+'\n\n'+text+'\n\n```powershell\n'+code+'\n```\n'
readme+='\n## How the app was built\n\n'
for s in steps:readme+='\n### '+str(s['number'])+'. '+s['title']+'\n\n'+s['explanation']+'\n\nSource: '+s['source']+'\n\n```'+s['language']+'\n'+s['code']+'\n```\n'
for a,b in reference:readme+='\n### '+a+'\n\n'+b+'\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 58 pages and 13 source-linked code steps.')
